import{_ as e,o,c as r,a0 as i}from"./chunks/framework.Bmhw_dvp.js";const b=JSON.parse('{"title":"视频源 · 新手教程","description":"","frontmatter":{},"headers":[],"relativePath":"features/video-sources.md","filePath":"features/video-sources.md","lastUpdated":1788515531000}'),l={name:"features/video-sources.md"};function a(n,t,s,d,g,h){return o(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="视频源-·-新手教程" tabindex="-1">视频源 · 新手教程 <a class="header-anchor" href="#视频源-·-新手教程" aria-label="Permalink to &quot;视频源 · 新手教程&quot;">​</a></h1><blockquote><p>从 B 站追番到自建 NAS，一文掌握 ZViewer 全部视频来源。</p></blockquote><hr><h2 id="_1-功能概述" tabindex="-1">1. 功能概述 <a class="header-anchor" href="#_1-功能概述" aria-label="Permalink to &quot;1. 功能概述&quot;">​</a></h2><p>ZViewer 支持 <strong>9 种视频来源</strong>，覆盖在线视频平台、直链播放、自建存储和第三方番剧源。在房间的 <strong>「添加影片」</strong> 面板中，你可以根据需求随时切换视频源。</p><table tabindex="0"><thead><tr><th>来源</th><th>适用场景</th><th>是否需要额外配置</th></tr></thead><tbody><tr><td><strong>Bilibili</strong></td><td>解析 B 站视频链接 / BV 号，支持大会员清晰度</td><td>可选（绑定账号获取大会员画质）</td></tr><tr><td><strong>MP4 直链</strong></td><td>直接播放任意可访问的 MP4 视频地址</td><td>无需</td></tr><tr><td><strong>WebDAV</strong></td><td>挂载自建 NAS、群晖、NextCloud 等 WebDAV 服务</td><td>需在个人资料页配置挂载点</td></tr><tr><td><strong>FTP</strong></td><td>挂载 FTP 文件服务器</td><td>需在个人资料页配置挂载点</td></tr><tr><td><strong>OpenList</strong></td><td>挂载 OpenList 目录列表服务</td><td>需在个人资料页配置挂载点</td></tr><tr><td><strong>Emby</strong></td><td>挂载 Emby 媒体服务器，浏览媒体库选片播放</td><td>需在个人资料页配置挂载点</td></tr><tr><td><strong>Jellyfin</strong></td><td>挂载 Jellyfin 媒体服务器，浏览媒体库选片播放</td><td>需在个人资料页配置挂载点</td></tr><tr><td><strong>番剧源（正处于开发中，暂不可用）</strong></td><td>Kazumi / AniSubs 等第三方番剧数据源</td><td>需在管理后台开启</td></tr><tr><td><strong>服务器文件</strong></td><td>浏览服务器本地的视频文件目录</td><td>仅 <code>root</code> 用户可用，需配置根目录</td></tr></tbody></table><hr><h2 id="_2-bilibili" tabindex="-1">2. Bilibili <a class="header-anchor" href="#_2-bilibili" aria-label="Permalink to &quot;2. Bilibili&quot;">​</a></h2><p>Bilibili 是 ZViewer 最常用的视频源。你可以直接粘贴 B 站视频链接或 BV 号，解析后即可播放。</p><h3 id="_2-1-添加-b-站视频" tabindex="-1">2.1 添加 B 站视频 <a class="header-anchor" href="#_2-1-添加-b-站视频" aria-label="Permalink to &quot;2.1 添加 B 站视频&quot;">​</a></h3><ol><li>进入房间后，在底部找到 <strong>「添加影片」</strong> 面板。</li><li>切换到 <strong>「B站」</strong> Tab。</li><li>粘贴 Bilibili 视频链接、<strong>BV 号</strong> 或 <strong>AV 号</strong>，例如： <ul><li>完整链接：<code>https://www.bilibili.com/video/BV1GJ411x7o</code></li><li>仅 BV 号：<code>BV1GJ411x7o</code></li><li>仅 AV 号：<code>av123456</code></li></ul></li><li>点击 <strong>「解析」</strong> 按钮，等待解析完成。</li><li>解析成功后，视频会自动添加到影片列表中，点击即可播放。</li></ol><h3 id="_2-2-切换清晰度" tabindex="-1">2.2 切换清晰度 <a class="header-anchor" href="#_2-2-切换清晰度" aria-label="Permalink to &quot;2.2 切换清晰度&quot;">​</a></h3><p>解析完成后，视频默认使用最高可用清晰度播放。你可以在播放器中点击 <strong>「画质」</strong> 按钮切换清晰度。</p><blockquote><p>未登录 B 站账号时，可选的清晰度以 <strong>B 站公开画质</strong> 为准，通常为 1080P 及以下。</p></blockquote><h3 id="_2-3-绑定-b-站账号-获取大会员清晰度" tabindex="-1">2.3 绑定 B 站账号（获取大会员清晰度） <a class="header-anchor" href="#_2-3-绑定-b-站账号-获取大会员清晰度" aria-label="Permalink to &quot;2.3 绑定 B 站账号（获取大会员清晰度）&quot;">​</a></h3><p>如果你拥有 B 站大会员，可以绑定账号以解锁 <strong>1080P 高码率</strong>、<strong>4K</strong> 等大会员专属画质。</p><p>ZViewer 提供两种绑定方式：</p><p><strong>方式一：扫码登录</strong></p><ol><li>在 ZViewer 首页，点击右上角 <strong>用户菜单</strong>（显示你的用户名），选择 <strong>「个人资料」</strong>。</li><li>在个人资料页，找到 <strong>「Bilibili 绑定」</strong> 区域。</li><li>点击 <strong>「绑定 B 站账号」</strong>，页面会显示一个二维码。</li><li>打开 B 站手机 App，使用扫一扫功能扫描二维码，确认登录。</li><li>绑定成功后，个人资料页会显示你的 B 站用户名和头像。</li></ol><p><strong>方式二：Cookie 登录</strong></p><ol><li>在个人资料页的「Bilibili 绑定」区域，选择 <strong>Cookie 登录</strong>。</li><li>粘贴你的 B 站登录 Cookie 字符串。</li><li>点击确认，系统验证 Cookie 有效性后完成绑定。</li></ol><blockquote><p>绑定后，后续解析的所有 B 站视频都会尝试使用大会员清晰度。如果大会员过期，系统会自动回退到公开画质。</p></blockquote><h3 id="_2-4-弹幕支持" tabindex="-1">2.4 弹幕支持 <a class="header-anchor" href="#_2-4-弹幕支持" aria-label="Permalink to &quot;2.4 弹幕支持&quot;">​</a></h3><p>ZViewer 支持加载 B 站官方弹幕。播放 B 站视频时，点击播放器中的 <strong>「弹幕」</strong> 按钮即可加载和显示弹幕。</p><hr><h2 id="_3-直链" tabindex="-1">3. 直链 <a class="header-anchor" href="#_3-直链" aria-label="Permalink to &quot;3. 直链&quot;">​</a></h2><p>如果你有一个视频文件的直接 HTTP 链接（以 <code>.mp4</code> 结尾或其他可播放格式如<code>.m3u8</code>等大部分流媒体格式 ），可以直接添加到房间播放（需无防盗链）。</p><h3 id="添加步骤" tabindex="-1">添加步骤 <a class="header-anchor" href="#添加步骤" aria-label="Permalink to &quot;添加步骤&quot;">​</a></h3><ol><li>在 <strong>「添加影片」</strong> 面板中，切换到 <strong>「直接链接」</strong> Tab。</li><li>在输入框中粘贴视频文件的直链 URL，例如： <ul><li><code>https://example.com/videos/my-movie.mp4</code></li><li><code>https://cdn.example.com/stream/abc123.mp4</code></li></ul></li><li>点击 <strong>「添加」</strong> 按钮。</li><li>视频会立即添加到影片列表中，点击即可播放。</li></ol><blockquote><p>确保链接可公开访问，且服务器未设置防盗链（Referer 限制）。如果遇到播放失败，可以尝试将链接粘贴到浏览器地址栏中测试是否可访问。</p></blockquote><h3 id="字幕支持" tabindex="-1">字幕支持 <a class="header-anchor" href="#字幕支持" aria-label="Permalink to &quot;字幕支持&quot;">​</a></h3><p>ZViewer 提供原生字幕系统，<strong>不再转换为 WebVTT</strong>，而是直接解析各字幕格式并用 HTML/CSS 渲染：</p><ul><li>支持常见字幕格式（SRT、ASS 等），原生解析，样式还原度更高。</li><li>支持<strong>自动识别</strong>、<strong>自动添加</strong>、<strong>手动添加</strong>三种字幕加载方式。</li><li>内置浏览器端播放引擎 <strong>playsvideo</strong>：<strong>MKV / AVI / TS / WMV</strong> 等浏览器无法直接播放的容器会在浏览器内自动重封装为 fMP4 播放；<strong>DTS / AC3 / EAC3 等浏览器不兼容音轨</strong>会在浏览器内实时转码为 AAC。全程自动生效，<strong>无需任何管理后台开关</strong>，也无需在添加影片时手动勾选；转码核心随前端资源自动分发，无需服务端 FFmpeg。</li></ul><blockquote><p>关于外挂字幕加载方式、内封字幕（内嵌字幕轨道）的识别与播放的完整说明，见 <strong><a href="/features/subtitles">字幕系统</a></strong>。</p></blockquote><hr><h2 id="_4-webdav-ftp-openlist" tabindex="-1">4. WebDAV / FTP / OpenList <a class="header-anchor" href="#_4-webdav-ftp-openlist" aria-label="Permalink to &quot;4. WebDAV / FTP / OpenList&quot;">​</a></h2><p>这三种视频源需要先在个人资料页配置 <strong>挂载点</strong>，之后在房间内浏览挂载目录选择视频播放。</p><h3 id="_4-1-配置挂载点" tabindex="-1">4.1 配置挂载点 <a class="header-anchor" href="#_4-1-配置挂载点" aria-label="Permalink to &quot;4.1 配置挂载点&quot;">​</a></h3><ol><li>点击右上角 <strong>用户菜单</strong> → <strong>「个人资料」</strong>。</li><li>在个人资料页，找到 <strong>「挂载点管理」</strong> 区域。</li><li>根据你的服务器类型，点击对应的 <strong>「添加」</strong> 按钮（WebDAV / FTP / OpenList）。</li><li>在弹出的表单中填写连接信息：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><strong>名称</strong></td><td>给这个挂载点起个名字，方便识别</td><td><code>我的 NAS</code> / <code>办公室 FTP</code></td></tr><tr><td><strong>服务器地址</strong></td><td>服务器 IP 或域名</td><td><code>192.168.1.100</code> 或 <code>nas.example.com</code></td></tr><tr><td><strong>端口</strong></td><td>服务端口号</td><td>WebDAV 默认 <code>443</code>（HTTPS）或 <code>80</code>（HTTP），FTP 默认 <code>21</code></td></tr><tr><td><strong>用户名</strong></td><td>登录用户名</td><td><code>admin</code></td></tr><tr><td><strong>密码</strong></td><td>登录密码</td><td><code>********</code></td></tr><tr><td><strong>路径</strong></td><td>可选，指定起始目录</td><td><code>/video</code>（留空则从根目录开始）</td></tr></tbody></table><ol start="5"><li>填写完成后，点击 <strong>「测试连接」</strong> 按钮，确认连接成功。</li><li>测试通过后，点击 <strong>「保存」</strong>。</li></ol><blockquote><p>如果测试连接失败，请检查服务器地址、端口、用户名和密码是否正确，以及服务器是否允许外部访问。</p><p><strong>OpenList 特别提醒</strong>：请确保你的 OpenList 站点和账户已授予 <strong>离线下载权限</strong>（支持直链播放）和 <strong>WebDAV 权限</strong>，否则无法正常挂载。</p></blockquote><h3 id="_4-2-在房间内使用挂载点" tabindex="-1">4.2 在房间内使用挂载点 <a class="header-anchor" href="#_4-2-在房间内使用挂载点" aria-label="Permalink to &quot;4.2 在房间内使用挂载点&quot;">​</a></h3><ol><li>回到房间，在 <strong>「添加影片」</strong> 面板中，切换到对应的挂载 Tab（<strong>「WebDAV」</strong> / <strong>「FTP」</strong> / <strong>「OpenList」</strong>）。</li><li>面板会列出你在个人资料页配置的所有挂载点。</li><li>点击一个挂载点，进入目录浏览模式。</li><li>浏览文件夹，找到视频文件（支持 <code>.mp4</code>、<code>.mkv</code>、<code>.webm</code> 等格式）。</li><li>点击视频文件，即可添加到影片列表并播放。</li></ol><h3 id="_4-3-管理挂载点" tabindex="-1">4.3 管理挂载点 <a class="header-anchor" href="#_4-3-管理挂载点" aria-label="Permalink to &quot;4.3 管理挂载点&quot;">​</a></h3><p>在个人资料页的 <strong>「挂载点管理」</strong> 区域，你可以：</p><ul><li><strong>编辑</strong>：点击挂载点旁的 <strong>「编辑」</strong> 图标，修改连接信息。</li><li><strong>删除</strong>：点击 <strong>「删除」</strong> 图标移除不再使用的挂载点。</li><li><strong>测试</strong>：随时点击 <strong>「测试连接」</strong> 检查挂载点是否可用。</li></ul><hr><h2 id="_5-emby-jellyfin" tabindex="-1">5. Emby / Jellyfin <a class="header-anchor" href="#_5-emby-jellyfin" aria-label="Permalink to &quot;5. Emby / Jellyfin&quot;">​</a></h2><p>Emby 与 Jellyfin 是流行的家庭媒体服务器，ZViewer 支持将两者作为视频源挂载，直接浏览媒体库（电影、剧集、季、单集）并逐级选择影片加入房间播放。</p><h3 id="_5-1-配置挂载点" tabindex="-1">5.1 配置挂载点 <a class="header-anchor" href="#_5-1-配置挂载点" aria-label="Permalink to &quot;5.1 配置挂载点&quot;">​</a></h3><ol><li>点击右上角 <strong>用户菜单</strong> → <strong>「个人资料」</strong>。</li><li>在个人资料页，找到 <strong>「挂载点管理」</strong> 区域。</li><li>点击 <strong>「添加」</strong> 按钮，选择 <strong>Emby</strong> 或 <strong>Jellyfin</strong>。</li><li>在弹出的表单中填写连接信息：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><strong>名称</strong></td><td>给这个挂载点起个名字</td><td><code>我的 Emby</code> / <code>家庭 Jellyfin</code></td></tr><tr><td><strong>服务器地址</strong></td><td>Emby/Jellyfin 服务器地址（含协议）</td><td><code>http://192.168.1.100:8096</code></td></tr><tr><td><strong>API Key</strong></td><td>Emby/Jellyfin 的 API 密钥（推荐）</td><td><code>xxxxxxxxxxxxxxxx</code></td></tr><tr><td><strong>用户名 / 密码</strong></td><td>账号密码（与 API Key 二选一）</td><td><code>admin</code> / <code>********</code></td></tr></tbody></table><blockquote><p><strong>API Key 与账号密码任选其一即可</strong>。推荐使用 API Key（在 Emby/Jellyfin 管理后台的「高级」→「API 密钥」中生成），更安全且不易受密码策略影响。</p></blockquote><ol start="5"><li>填写完成后，点击 <strong>「测试连接」</strong> 按钮，确认连接成功并显示登录用户。</li><li>测试通过后，点击 <strong>「保存」</strong>。</li></ol><h3 id="_5-2-在房间内使用-emby-jellyfin" tabindex="-1">5.2 在房间内使用 Emby / Jellyfin <a class="header-anchor" href="#_5-2-在房间内使用-emby-jellyfin" aria-label="Permalink to &quot;5.2 在房间内使用 Emby / Jellyfin&quot;">​</a></h3><ol><li>回到房间，在 <strong>「添加影片」</strong> 面板中，切换到 <strong>「Emby」</strong> 或 <strong>「Jellyfin」</strong> Tab。</li><li>面板会列出你配置的 Emby/Jellyfin 挂载点。</li><li>点击一个挂载点，进入媒体库浏览模式（双列布局，与 WebDAV/OpenList 一致）。</li><li>逐级浏览：<strong>媒体库</strong> → <strong>电影 / 剧集</strong> → <strong>季</strong> → <strong>单集</strong>。</li><li>点击影片（或勾选多个）即可批量添加到影片列表并播放。</li></ol><h3 id="_5-3-播放模式" tabindex="-1">5.3 播放模式 <a class="header-anchor" href="#_5-3-播放模式" aria-label="Permalink to &quot;5.3 播放模式&quot;">​</a></h3><p>添加影片时，可通过 <strong>「播放方式」</strong> 下拉选择：</p><table tabindex="0"><thead><tr><th>模式</th><th>说明</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>服务器转发</strong></td><td>播放列表中的地址指向 ZViewer 后端的中转端点，由后端携带 Emby/Jellyfin 凭据请求媒体流</td><td>默认模式，浏览器无法直接设置 Referer/Authorization 头的场景</td></tr><tr><td><strong>直链直连</strong></td><td>播放器直接访问 Emby/Jellyfin 服务器下发的媒体流地址</td><td>媒体服务器与观众网络可达、无跨域限制的场景，可减少服务器中转流量</td></tr></tbody></table><blockquote><p><strong>提示</strong>：Emby 与 Jellyfin 的 API 高度兼容，ZViewer 使用同一套客户端实现，因此两者功能完全一致。</p></blockquote><h3 id="_5-4-管理挂载点" tabindex="-1">5.4 管理挂载点 <a class="header-anchor" href="#_5-4-管理挂载点" aria-label="Permalink to &quot;5.4 管理挂载点&quot;">​</a></h3><p>在个人资料页的 <strong>「挂载点管理」</strong> 区域，你可以对 Emby/Jellyfin 挂载点执行<strong>编辑</strong>、<strong>删除</strong>、<strong>测试连接</strong>操作，与 WebDAV/FTP/OpenList 一致。</p><hr><h2 id="_6-番剧源-kazumi-anisubs-beta" tabindex="-1">6. 番剧源（Kazumi / AniSubs，Beta） <a class="header-anchor" href="#_6-番剧源-kazumi-anisubs-beta" aria-label="Permalink to &quot;6. 番剧源（Kazumi / AniSubs，Beta）&quot;">​</a></h2><p>番剧源是 ZViewer 的 Beta 功能，支持通过 Kazumi 或 AniSubs 等第三方数据源搜索和播放番剧。</p><h3 id="_6-1-开启番剧源" tabindex="-1">6.1 开启番剧源 <a class="header-anchor" href="#_6-1-开启番剧源" aria-label="Permalink to &quot;6.1 开启番剧源&quot;">​</a></h3><blockquote><p>番剧源为 Beta 功能，正在开发中ING</p></blockquote><hr><h2 id="_7-服务器文件-仅-root" tabindex="-1">7. 服务器文件（仅 root） <a class="header-anchor" href="#_7-服务器文件-仅-root" aria-label="Permalink to &quot;7. 服务器文件（仅 root）&quot;">​</a></h2><p><strong>服务器文件</strong> 功能允许 <code>root</code> 用户直接访问服务器上的本地视频目录，无需额外搭建文件服务。</p><h3 id="_7-1-配置文件根目录" tabindex="-1">7.1 配置文件根目录 <a class="header-anchor" href="#_7-1-配置文件根目录" aria-label="Permalink to &quot;7.1 配置文件根目录&quot;">​</a></h3><ol><li>使用 <code>root</code> 账号登录。</li><li>进入 <strong>管理后台</strong> → <strong>「基础设置」</strong>。</li><li>找到 <strong>「服务器文件根目录」</strong> 配置项。</li><li>输入服务器上的一个或多个目录路径（逗号分隔），例如： <ul><li><code>/mnt/videos</code></li><li><code>/data/media</code></li></ul></li><li>保存设置。</li></ol><blockquote><p>确保 ZViewer 后端进程对这些目录有<strong>读取权限</strong>。目录路径是服务器上的绝对路径，不是浏览器所在机器的路径。</p></blockquote><h3 id="_7-2-浏览和管理文件" tabindex="-1">7.2 浏览和管理文件 <a class="header-anchor" href="#_7-2-浏览和管理文件" aria-label="Permalink to &quot;7.2 浏览和管理文件&quot;">​</a></h3><ol><li>在房间的 <strong>「添加影片」</strong> 面板中，切换到 <strong>「服务器文件」</strong> Tab。</li><li>你会看到配置的根目录列表。</li><li>点击目录进入浏览模式，可以： <ul><li><strong>浏览文件夹</strong>：层层进入，找到视频文件。</li><li><strong>上传文件</strong>：点击 <strong>「上传」</strong> 按钮，选择本地文件上传到当前目录（支持批量上传，最多 50 个文件）。</li><li><strong>新建文件夹</strong>：点击 <strong>「新建文件夹」</strong> 创建子目录。</li><li><strong>重命名/删除</strong>：对文件或文件夹执行重命名或删除操作。</li></ul></li><li>点击视频文件，即可添加到影片列表播放。</li></ol><blockquote><p>服务器文件的播放通过 ZViewer 后端代理，支持 Range 断点续传，拖动进度条非常流畅。</p></blockquote><hr><h2 id="_8-zviewercli-本地代理" tabindex="-1">8. ZViewerCLI 本地代理 <a class="header-anchor" href="#_8-zviewercli-本地代理" aria-label="Permalink to &quot;8. ZViewerCLI 本地代理&quot;">​</a></h2><p>ZViewerCLI 是一个可选但<strong>强烈推荐</strong>的本地代理客户端，主要解决两个问题：</p><ul><li><strong>大会员高画质</strong>：通过使用你本地浏览器的 B 站 Cookie 来解析大会员画质地址。</li><li><strong>CORS 与防盗链</strong>：某些 CDN 会限制跨域请求或校验 Referer，ZViewerCLI 在本地代理转发，自动注入正确的请求头。</li></ul><h3 id="_8-1-安装-zviewercli" tabindex="-1">8.1 安装 ZViewerCLI <a class="header-anchor" href="#_8-1-安装-zviewercli" aria-label="Permalink to &quot;8.1 安装 ZViewerCLI&quot;">​</a></h3><ol><li>打开 <a href="https://github.com/Zero-wyc/ZViewerCLI/releases" target="_blank" rel="noreferrer">ZViewerCLI Releases 页面</a>。</li><li>根据你的操作系统下载对应版本： <ul><li><strong>Windows</strong>：下载 <code>zviewer-cli-windows-x64.zip</code></li><li><strong>Linux</strong>：下载 <code>zviewer-cli-linux-x64.tar.gz</code></li></ul></li><li>解压到任意文件夹。</li></ol><h3 id="_8-2-启动-zviewercli" tabindex="-1">8.2 启动 ZViewerCLI <a class="header-anchor" href="#_8-2-启动-zviewercli" aria-label="Permalink to &quot;8.2 启动 ZViewerCLI&quot;">​</a></h3><p><strong>Windows</strong>：双击 <code>zviewer-cli.exe</code>，或在终端中运行：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">zviewer-cli.exe</span></span></code></pre></div><p><strong>Linux</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./zviewer-cli</span></span></code></pre></div><p>启动后，ZViewerCLI 会自动通过 WebSocket 向 ZViewer 服务器注册。前端<strong>自动检测</strong>到本地代理后，会优先使用本地代理解析视频流。</p><h3 id="_8-3-验证" tabindex="-1">8.3 验证 <a class="header-anchor" href="#_8-3-验证" aria-label="Permalink to &quot;8.3 验证&quot;">​</a></h3><p>ZViewerCLI 启动后，在 ZViewer 中播放 B 站视频时，如果看到画质选项中出现了之前不可用的高清晰度（如 <strong>1080P 高码率</strong>、<strong>4K</strong>），说明代理已生效。</p><blockquote><p>ZViewerCLI 只需要在<strong>观看端</strong>的本地机器上运行，不需要在服务器上安装。如果多人观看，每个人都可以在自己的机器上运行 ZViewerCLI 以获得最佳画质。</p></blockquote><hr><h2 id="_9-常见问题" tabindex="-1">9. 常见问题 <a class="header-anchor" href="#_9-常见问题" aria-label="Permalink to &quot;9. 常见问题&quot;">​</a></h2><h3 id="q-为什么我添加的-b-站视频解析失败" tabindex="-1">Q：为什么我添加的 B 站视频解析失败？ <a class="header-anchor" href="#q-为什么我添加的-b-站视频解析失败" aria-label="Permalink to &quot;Q：为什么我添加的 B 站视频解析失败？&quot;">​</a></h3><p>A：可能的原因：</p><ul><li>BV 号或链接格式不正确，请检查是否完整复制。</li><li>该视频为 B 站不可公开访问的视频（如私密投稿）。</li><li>服务器网络无法访问 B 站 API。</li><li>如果开启了 ZViewerCLI，请确认 CLI 正在运行。</li></ul><h3 id="q-mp4-直链添加后无法播放" tabindex="-1">Q：MP4 直链添加后无法播放？ <a class="header-anchor" href="#q-mp4-直链添加后无法播放" aria-label="Permalink to &quot;Q：MP4 直链添加后无法播放？&quot;">​</a></h3><p>A：请检查：</p><ul><li>链接是否以 <code>https://</code> 或 <code>http://</code> 开头。</li><li>链接是否可在浏览器中直接打开。</li><li>目标服务器是否设置了防盗链（Referer 限制）。</li><li>视频格式是否受支持（<code>.mp4</code> / <code>.mkv</code> / <code>.avi</code> / <code>.ts</code> / <code>.wmv</code> 等均可，浏览器无法直接播放的容器会由 playsvideo 引擎自动重封装）。</li></ul><h3 id="q-webdav-ftp-连接测试失败" tabindex="-1">Q：WebDAV / FTP 连接测试失败？ <a class="header-anchor" href="#q-webdav-ftp-连接测试失败" aria-label="Permalink to &quot;Q：WebDAV / FTP 连接测试失败？&quot;">​</a></h3><p>A：常见原因：</p><ul><li>服务器地址或端口填写错误。</li><li>用户名或密码不正确。</li><li>服务器防火墙阻止了外部连接。</li><li>WebDAV 服务器未启用 HTTPS（某些浏览器限制 HTTPS 页面访问 HTTP 资源）。</li><li>如果是自建 NAS，请检查是否开启了对应服务。</li></ul><h3 id="q-番剧源搜索不到结果" tabindex="-1">Q：番剧源搜索不到结果？ <a class="header-anchor" href="#q-番剧源搜索不到结果" aria-label="Permalink to &quot;Q：番剧源搜索不到结果？&quot;">​</a></h3><p>A：番剧源为 Beta 功能，可能的原因：</p><ul><li>管理后台未开启番剧源开关。</li><li>数据源配置为空或失效。</li><li>番剧名称不准确，尝试使用日文原名或中文译名。</li><li>数据源服务器暂时不可用。</li></ul><h3 id="q-emby-jellyfin-连接测试失败" tabindex="-1">Q：Emby / Jellyfin 连接测试失败？ <a class="header-anchor" href="#q-emby-jellyfin-连接测试失败" aria-label="Permalink to &quot;Q：Emby / Jellyfin 连接测试失败？&quot;">​</a></h3><p>A：常见原因：</p><ul><li>服务器地址格式错误，需要包含协议（如 <code>http://192.168.1.100:8096</code>）。</li><li>API Key 或用户名/密码不正确。</li><li>Emby/Jellyfin 服务器未开启外部访问。</li><li>服务器防火墙阻止了连接。</li></ul><h3 id="q-emby-jellyfin-播放时卡顿或黑屏" tabindex="-1">Q：Emby / Jellyfin 播放时卡顿或黑屏？ <a class="header-anchor" href="#q-emby-jellyfin-播放时卡顿或黑屏" aria-label="Permalink to &quot;Q：Emby / Jellyfin 播放时卡顿或黑屏？&quot;">​</a></h3><p>A：请尝试切换播放方式：</p><ul><li>当前为 <strong>直链直连</strong> 时，切换到 <strong>服务器转发</strong>（浏览器防盗链限制）。</li><li>当前为 <strong>服务器转发</strong> 时，若网络条件允许可切换到 <strong>直链直连</strong> 减少中转开销。</li></ul><h3 id="q-zviewercli-启动后没有效果" tabindex="-1">Q：ZViewerCLI 启动后没有效果？ <a class="header-anchor" href="#q-zviewercli-启动后没有效果" aria-label="Permalink to &quot;Q：ZViewerCLI 启动后没有效果？&quot;">​</a></h3><p>A：请检查：</p><ul><li>ZViewerCLI 是否成功启动（终端是否有报错信息）。</li><li>是否在<strong>观看端</strong>本地运行（不是在服务器上运行）。</li><li>防火墙是否阻止了 ZViewerCLI 的网络连接。</li><li>尝试重启 ZViewerCLI 和刷新 ZViewer 页面。</li></ul><h3 id="q-如何查看我绑定了哪些视频源" tabindex="-1">Q：如何查看我绑定了哪些视频源？ <a class="header-anchor" href="#q-如何查看我绑定了哪些视频源" aria-label="Permalink to &quot;Q：如何查看我绑定了哪些视频源？&quot;">​</a></h3><p>A：在个人资料页中，你可以看到：</p><ul><li><strong>Bilibili 绑定状态</strong>：显示已绑定的用户名。</li><li><strong>挂载点列表</strong>：显示所有已配置的 WebDAV / FTP / OpenList 挂载点。</li></ul><h3 id="q-服务器文件功能为什么看不到" tabindex="-1">Q：服务器文件功能为什么看不到？ <a class="header-anchor" href="#q-服务器文件功能为什么看不到" aria-label="Permalink to &quot;Q：服务器文件功能为什么看不到？&quot;">​</a></h3><p>A：服务器文件功能仅对 <strong><code>root</code> 角色</strong>可见。如果你使用普通用户账号登录，该 Tab 不会显示。请联系管理员或使用 <code>root</code> 账号登录。</p><hr><blockquote><p>更多问题？查看<a href="/guide/faq">常见问题 FAQ</a> 或联系管理员。</p></blockquote>',122)])])}const u=e(l,[["render",a]]);export{b as __pageData,u as default};
